"use client";

import { useMemo } from "react";
import BioreactorDiagram from "@/components/BioreactorDiagram";
import type {
  ProcessInputs,
  OrganismClass,
  OrganismSpecies,
  ProcessType,
  RiskScore,

} from "@/lib/types";
import { runAssessment } from "@/lib/engine";
import type { PartialAssessmentResult } from "@/lib/engine";
import { INPUT_DEFAULTS } from "@/lib/constants";

// Mirrors FormState from InputForm — kept in sync manually
export interface PreviewFormState {
  organism_class: OrganismClass | "";
  organism_species: OrganismSpecies | "";
  process_type: ProcessType | "";
  batch_x0?: string;
  batch_s0?: string;
  fed_batch_fill_pct?: string;
  fed_batch_time_h?: string;
  v_lab: string;
  v_target: string;
  h_d_lab: string;
  h_d_target: string;
  n_impellers: string;
  impeller_type: string;
  rpm: string;
  vvm: string;
  biomass: string;
  biomass_unit: string;
  our_mode: string;
  our_measured: string;
  do_setpoint: string;
  temperature: string;
  t_cw_inlet: string;
  cooling_water_flowrate?: string;
  // optional / legacy
  vessel_model?: string;
  our_estimate_override?: string;
  n_impellers_overridden?: boolean;
}

interface LivePreviewProps {
  formState: PreviewFormState | null;
}

// Risk domain display config
const DOMAIN_CONFIG: {
  key: string;
  label: string;
  icon: string;
  colorVar: string;
}[] = [
  { key: "otr", label: "Oxygen Transfer", icon: "O\u2082", colorVar: "otr" },
  { key: "mixing", label: "Mixing", icon: "\u21bb", colorVar: "mixing" },
  { key: "shear", label: "Shear Stress", icon: "\u26a1", colorVar: "shear" },
  { key: "co2", label: "CO\u2082 Accumulation", icon: "CO\u2082", colorVar: "co2" },
  { key: "heat", label: "Heat Removal", icon: "\u0394T", colorVar: "heat" },
];

function getRiskColor(score: RiskScore): string {
  switch (score) {
    case "low": return "text-risk-low";
    case "moderate": return "text-risk-moderate";
    case "high": return "text-risk-high";
    case "critical": return "text-risk-critical";
  }
}

function getRiskBg(score: RiskScore): string {
  switch (score) {
    case "low": return "bg-risk-low/[0.08] border-risk-low/20";
    case "moderate": return "bg-risk-moderate/[0.08] border-risk-moderate/20";
    case "high": return "bg-risk-high/[0.08] border-risk-high/20";
    case "critical": return "bg-risk-critical/[0.08] border-risk-critical/20";
  }
}

function getRiskGlow(score: RiskScore): string {
  switch (score) {
    case "low": return "risk-glow-low";
    case "moderate": return "risk-glow-moderate";
    case "high": return "risk-glow-high";
    case "critical": return "risk-glow-critical";
  }
}

function getDomainKeyNumber(key: string, results: PartialAssessmentResult): string {
  switch (key) {
    case "otr": return `kLa ratio: ${results.otr.kla_ratio.toFixed(2)}`;
    case "mixing": return `\u03B8_mix: ${results.mixing.theta_mix_target.toFixed(0)}s`;
    case "shear": return `Tip: ${results.shear.tip_speed.toFixed(1)} m/s`;
    case "co2": return results.co2.activated && results.co2.pco2_bottom
      ? `pCO\u2082: ${results.co2.pco2_bottom.toFixed(3)} bar`
      : "Below threshold";
    case "heat": return `Q ratio: ${results.heat.heat_ratio.toFixed(2)}`;
    default: return "";
  }
}

function getDomainScore(key: string, results: PartialAssessmentResult): RiskScore {
  switch (key) {
    case "otr": return results.otr.score;
    case "mixing": return results.mixing.score;
    case "shear": return results.shear.score;
    case "co2": return results.co2.score;
    case "heat": return results.heat.score;
    default: return "low";
  }
}

export default function LivePreview({ formState }: LivePreviewProps) {
  // Count filled fields for progress
  const progress = useMemo(() => {
    if (!formState) return { filled: 0, total: 7, percentage: 0 };
    let filled = 0;
    const total = 7; // minimum required fields
    if (formState.organism_class) filled++;
    if (formState.organism_species) filled++;
    if (formState.v_lab && parseFloat(formState.v_lab) > 0) filled++;
    if (formState.v_target && parseFloat(formState.v_target) > 0) filled++;
    if (formState.rpm && parseFloat(formState.rpm) > 0) filled++;
    if (formState.biomass && parseFloat(formState.biomass) > 0) filled++;
    if (formState.temperature && parseFloat(formState.temperature) > 0) filled++;
    return { filled, total, percentage: Math.round((filled / total) * 100) };
  }, [formState]);

  // Try to run assessment with available data
  const liveResults = useMemo<PartialAssessmentResult | null>(() => {
    if (!formState) return null;

    // Minimum required: organism_class, organism_species, v_lab, v_target, rpm, biomass, temperature
    const oc = formState.organism_class;
    const os = formState.organism_species;
    const vLab = parseFloat(formState.v_lab);
    const vTarget = parseFloat(formState.v_target);
    const rpm = parseFloat(formState.rpm);
    const biomass = parseFloat(formState.biomass);
    const temp = parseFloat(formState.temperature);

    if (
      !oc || !os ||
      isNaN(vLab) || vLab <= 0 ||
      isNaN(vTarget) || vTarget <= vLab ||
      isNaN(rpm) || rpm <= 0 ||
      isNaN(biomass) || biomass <= 0 ||
      isNaN(temp) || temp <= 0
    ) {
      return null;
    }

    try {
      const inputs: ProcessInputs = {
        organism_class: oc as ProcessInputs["organism_class"],
        organism_species: os as ProcessInputs["organism_species"],
        process_type: (formState.process_type || "batch") as ProcessInputs["process_type"],
        v_lab: vLab,
        v_target: vTarget,
        h_d_lab: parseFloat(formState.h_d_lab) || INPUT_DEFAULTS.h_d_lab,
        h_d_target: parseFloat(formState.h_d_target) || 1.0,
        n_impellers: parseInt(formState.n_impellers) || 1,
        impeller_type: (formState.impeller_type || "rushton") as ProcessInputs["impeller_type"],
        rpm,
        vvm: parseFloat(formState.vvm) || INPUT_DEFAULTS.vvm,
        biomass,
        biomass_unit: (formState.biomass_unit || "g_L_CDW") as ProcessInputs["biomass_unit"],
        our_mode: (formState.our_mode || "estimate") as ProcessInputs["our_mode"],
        our_measured: formState.our_mode === "measured" && formState.our_measured
          ? parseFloat(formState.our_measured)
          : undefined,
        do_setpoint: parseFloat(formState.do_setpoint) || INPUT_DEFAULTS.do_setpoint,
        temperature: temp,
        t_cw_inlet: parseFloat(formState.t_cw_inlet) || INPUT_DEFAULTS.t_cw_inlet,
        cooling_water_flowrate_lpm: formState.cooling_water_flowrate
          ? parseFloat(formState.cooling_water_flowrate)
          : INPUT_DEFAULTS.cooling_water_flowrate_lpm,
      };

      return runAssessment(inputs);
    } catch {
      return null;
    }
  }, [formState]);

  // Scale ratio
  const scaleRatio = useMemo(() => {
    if (!formState) return null;
    const lab = parseFloat(formState.v_lab);
    const target = parseFloat(formState.v_target);
    if (lab > 0 && target > lab) return target / lab;
    return null;
  }, [formState]);

  return (
    <div className="sticky top-8 space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between mb-1">
        <h3 className="text-xs font-semibold uppercase tracking-[0.12em] text-silver-500">
          Live Risk Preview
        </h3>
        <div className={`text-[10px] font-medium px-2 py-0.5 rounded-full border ${
          liveResults ? "border-risk-low/30 text-risk-low bg-risk-low/[0.06]" : "border-silver-700 text-silver-600"
        }`} style={{ ...(!liveResults ? { background: "var(--input-bg)" } : {}) }}>
          {liveResults ? "LIVE" : "AWAITING DATA"}
        </div>
      </div>

      {/* Bioreactor Diagram */}
      <div className="glass-panel-sm p-4">
        <div className="flex items-center justify-between mb-3">
          <span className="text-[11px] text-silver-500 uppercase tracking-[0.08em]">Target Vessel</span>
          {scaleRatio && (
            <span className="text-[10px] font-mono text-accent-warm font-medium">
              {scaleRatio.toLocaleString("en-GB", { maximumFractionDigits: 0 })}&times; scale-up
            </span>
          )}
        </div>
        <BioreactorDiagram
          hd={parseFloat(formState?.h_d_target || "") || 2.0}
          nImpellers={formState?.n_impellers ? parseInt(formState.n_impellers) || 1 : 1}
          impellerType={formState?.impeller_type || "rushton"}
          volume={formState?.v_target ? parseFloat(formState.v_target) || undefined : undefined}
          width={200}
        />
      </div>

      {/* Data Completeness */}
      <div className="glass-panel-sm p-4">
        <div className="flex items-center justify-between mb-2">
          <span className="text-[11px] text-silver-500 uppercase tracking-[0.08em]">Core Parameters</span>
          <span className="text-xs font-mono text-silver-300">{progress.filled}/{progress.total}</span>
        </div>
        <div className="flex gap-1">
          {Array.from({ length: progress.total }).map((_, i) => (
            <div
              key={i}
              className={`h-1 flex-1 rounded-full transition-all duration-300 ${
                i < progress.filled
                  ? "bg-accent/60"
                  : ""
              }`}
              style={i >= progress.filled ? { background: "var(--range-track)" } : {}}
            />
          ))}
        </div>
      </div>

      {/* Risk Domain Cards */}
      <div className="space-y-2">
        {DOMAIN_CONFIG.map((domain) => {
          const hasResults = liveResults !== null;
          const score = hasResults ? getDomainScore(domain.key, liveResults!) : null;
          const keyNumber = hasResults ? getDomainKeyNumber(domain.key, liveResults!) : null;

          return (
            <div
              key={domain.key}
              className={`glass-panel-sm p-3.5 transition-all duration-300 border ${
                hasResults && score
                  ? `${getRiskBg(score)} ${getRiskGlow(score)}`
                  : "opacity-40"
              }`}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2.5">
                  <span className={`text-sm font-mono w-8 text-center ${
                    hasResults && score ? getRiskColor(score) : "text-silver-700"
                  }`}>
                    {domain.icon}
                  </span>
                  <div>
                    <span className="text-xs font-medium text-silver-300">{domain.label}</span>
                    {keyNumber && (
                      <p className="text-[10px] text-silver-500 font-mono mt-0.5">{keyNumber}</p>
                    )}
                  </div>
                </div>
                {hasResults && score ? (
                  <span className={`risk-badge risk-badge-${score}`}>
                    {score}
                  </span>
                ) : (
                  <span className="text-[10px] text-silver-600 font-mono">&mdash;</span>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* Bottleneck Statement */}
      {liveResults && (
        <div className="glass-panel-sm p-4 border-accent/10">
          <p className="text-[10px] text-silver-500 uppercase tracking-[0.08em] mb-1.5">Primary Bottleneck</p>
          <p className="text-xs text-silver-200 leading-relaxed">
            {liveResults.primary_bottleneck.statement}
          </p>
          <p className="text-[10px] text-accent/70 mt-2 italic leading-relaxed">
            {liveResults.primary_bottleneck.what_would_change}
          </p>
        </div>
      )}

      {/* Hint when no results */}
      {!liveResults && progress.filled > 0 && (
        <div className="text-center py-3">
          <p className="text-[11px] text-accent/70 italic">
            {progress.total - progress.filled} more parameter{progress.total - progress.filled > 1 ? "s" : ""} needed for live preview
          </p>
        </div>
      )}
    </div>
  );
}

// TypeScript interfaces for Lemnisca Fermentation Scale-Up Risk Predictor
// All field IDs and structures per /docs/lemnisca_scaleup_app_dev_spec.md

// --- Enums and Literal Types ---

export type OrganismClass = "bacteria" | "yeast";

export type OrganismSpecies =
  | "e_coli"
  | "b_subtilis"
  | "s_cerevisiae"
  | "p_pastoris"
  | "other_bacteria"
  | "other_yeast";

export type ProcessType = "batch" | "fed_batch";

export type ImpellerType = "rushton" | "pitched_blade" | "marine" | "unknown";

export type BiomassUnit = "g_L_CDW" | "OD600";

// "exhaust_gas" retained for type-safety during transition; engine support
// will be dropped in Stage 3. New UI only exposes "measured" | "estimate".
export type OurMode = "measured" | "estimate" | "exhaust_gas";

/** @deprecated — will be removed in Stage 3. τ_feed now derived from fed_batch_config.batch_time_h. */
export type FeedFrequency = "continuous" | "1_10min" | "10_30min" | "30plus_min";

export type RiskScore = "low" | "moderate" | "high" | "critical";

export type Confidence = "high_confidence" | "reliable" | "directional";

// --- Batch / Fed-batch sub-configs (new in Stage 1) ---

export interface BatchConfig {
  x0_g_L: number;   // Initial biomass concentration (g/L CDW), default 0.5
  s0_g_L: number;   // Initial substrate concentration (g/L), default 20.0
}

export interface FedBatchConfig {
  initial_fill_pct: number;  // Initial fill as % of working volume, default 60
  batch_time_h: number;      // Duration of batch phase (h), default 24
}

// --- Input Parameters (Section 1.1) ---

export interface ProcessInputs {
  // Section A: Process Identity
  organism_class: OrganismClass;
  organism_species: OrganismSpecies;
  process_type: ProcessType;

  // Batch / fed-batch sub-configs (populated based on process_type)
  batch_config?: BatchConfig;
  fed_batch_config?: FedBatchConfig;

  // Section B: Scale Definition
  v_lab: number;        // Lab working volume (L), > 0, <= 1000
  v_target: number;     // Target working volume (L), > v_lab

  // Section C: Lab-scale Vessel & Agitation
  // Note: these describe the lab vessel; target geometry is derived from v_target + h_d_target.
  vessel_model?: string;            // Lab vessel brand/model (optional)
  h_d_lab: number;                  // H/D ratio (lab), default 1.2, range 0.5–4.0
  h_d_target: number;               // H/D ratio (target), range 0.5–4.0
  n_impellers: number;              // Number of impellers (lab vessel), 1–4
  impeller_type: ImpellerType;      // Default: rushton
  rpm: number;                      // Agitation at peak demand (RPM), > 0, <= 3000
  vvm: number;                      // Airflow at peak demand (VVM), default 1.0, 0.1–5.0

  // Section D: Oxygen & Biomass
  biomass: number;                  // Peak biomass, > 0, <= 200
  biomass_unit: BiomassUnit;        // Default: g_L_CDW
  our_mode: OurMode;                // OUR input mode, default: estimate
  our_measured?: number;            // OUR measured value (mmol/L/h), required if our_mode == measured
  /** @deprecated — exhaust_gas mode removed from UI in Stage 2 */
  o2_inlet?: number;                // Exhaust gas inlet O2 (%), default 20.9
  /** @deprecated */
  o2_outlet?: number;               // Exhaust gas outlet O2 (%)
  /** @deprecated */
  gas_flow?: number;                // Exhaust gas flow rate (L/min)
  do_setpoint: number;              // DO setpoint at control point (%), default 30, 0–100
  do_at_bottom_pct?: number;        // DO at vessel bottom (%), default 20; used for driving force in R1

  // Section D: Thermal
  temperature: number;              // Process temperature (°C), 15–55
  t_cw_inlet: number;               // Cooling water inlet temp (°C), default 12, 0–40
  cooling_water_flowrate_lpm?: number; // Cooling water flowrate (L/min), default 30

  // Section E: Fed-batch Parameters
  // feed_frequency and feed_interval_seconds are deprecated; τ_feed is now
  // derived from fed_batch_config.batch_time_h in Stage 3.
  /** @deprecated */
  feed_frequency?: FeedFrequency;
  /** @deprecated */
  feed_interval_seconds?: number;
}

// --- Derived Parameters (Section 2.1, D1–D7) ---

export interface VesselGeometry {
  t_diameter: number;    // Tank diameter (m)
  h_liquid: number;      // Liquid height (m)
  d_imp: number;         // Impeller diameter (m)
  a_cross: number;       // Cross-sectional area (m²)
  volume_m3: number;     // Working volume (m³)
}

export interface DerivedParameters {
  // D1 — OUR derivation
  our_peak: number;               // mmol/L/h
  our_min?: number;               // mmol/L/h (only when our_mode == estimate)
  our_max?: number;               // mmol/L/h (only when our_mode == estimate)

  // D2 — Vessel geometry
  lab_geometry: VesselGeometry;
  target_geometry: VesselGeometry;

  // D3 — Power input
  n_rps: number;                  // Revolutions per second
  p_ungassed: number;             // Ungassed power (W)
  p_gassed: number;               // Gassed power per impeller (W)
  p_total: number;                // Total gassed power (W)
  pv_lab: number;                 // P/V at lab scale (W/m³)

  // D4 — Reynolds number
  re: number;                     // Reynolds number (dimensionless)

  // D5 — Superficial gas velocity
  q_gas_lab: number;              // Gas flow rate at lab (m³/s)
  vs_lab: number;                 // Superficial gas velocity at lab (m/s)
  q_gas_target: number;           // Gas flow rate at target (m³/s)
  vs_target: number;              // Superficial gas velocity at target (m/s)

  // D6 — C* and driving force
  c_star: number;                 // O₂ saturation concentration (mmol/L)
  c_l: number;                    // Dissolved O₂ at DO setpoint (mmol/L)
  driving_force: number;          // c_star - c_l at DO setpoint (mmol/L)
  // Stage 4: bottom-of-vessel driving force using do_at_bottom_pct
  c_l_bottom?: number;            // Dissolved O₂ at vessel bottom (mmol/L)
  driving_force_bottom?: number;  // c_star - c_l_bottom (mmol/L)

  // D7 — Biomass conversion
  biomass_cdw: number;            // Biomass in g/L CDW (converted if OD600)

  // Viscosity at process temperature
  mu: number;                     // Dynamic viscosity (Pa·s)
}

// --- Risk Domain Results (Section 2.2) ---

export interface OtrRiskResult {
  score: RiskScore;
  kla_required: number;                     // h⁻¹
  kla_lab: number;                          // h⁻¹ (achievable at lab)
  kla_target_conservative: number;          // h⁻¹ (0.5× P/V)
  kla_target_moderate: number;              // h⁻¹ (1.0× P/V)
  kla_target_aggressive: number;            // h⁻¹ (2.0× P/V)
  kla_ratio: number;                        // achievable / required (moderate scenario)
  pv_conservative: number;                  // W/m³
  pv_moderate: number;                      // W/m³
  pv_aggressive: number;                    // W/m³
  correlation_used?: string;                // kLa correlation name (populated in Stage 4)
  confidence: Confidence;
  driver: string;
}

export interface MixingRiskResult {
  score: RiskScore;
  theta_mix_lab: number;                    // Lab mixing time (s)
  theta_mix_target: number;                 // Target mixing time (s)
  da?: number;                              // Damköhler number (fed-batch only)
  da_score?: RiskScore;                     // Da-based score (fed-batch only)
  ph_score: RiskScore;                      // pH control score
  confidence: Confidence;
  driver: string;
}

export interface ShearRiskResult {
  score: RiskScore;
  n_target: number;                         // Target impeller speed (rev/s)
  tip_speed: number;                        // Tip speed at target (m/s)
  tip_speed_threshold: number;              // Organism threshold (m/s)
  tip_speed_ratio: number;                  // tip_speed / threshold
  confidence: Confidence;
  driver: string;
}

export interface Co2RiskResult {
  score: RiskScore;
  activated: boolean;                       // Whether detailed calc was triggered
  cer?: number;                             // CO₂ evolution rate (mmol/L/h)
  kla_co2?: number;                         // kLa for CO₂ (h⁻¹)
  pco2_bulk?: number;                       // Bulk pCO₂ (bar)
  pco2_bottom?: number;                     // pCO₂ at vessel bottom (bar)
  dp_hydro?: number;                        // Hydrostatic pressure (Pa)
  confidence: Confidence;
  driver: string;
}

export interface HeatRiskResult {
  score: RiskScore;
  q_metabolic: number;                      // Metabolic heat generation (kW)
  a_jacket: number;                         // Jacket surface area (m²)
  dt_lm: number;                            // Log-mean temperature difference (K)
  q_cool_max: number;                       // Maximum cooling capacity (kW)
  heat_ratio: number;                       // Q_metabolic / Q_cool_max
  t_cw_outlet?: number;                     // Computed cooling water outlet temp (°C) — Stage 5
  confidence: Confidence;
  driver: string;
}

// --- Primary Bottleneck (Section 2.3) ---

export type RiskDomain = "otr" | "mixing" | "shear" | "co2" | "heat";

export interface PrimaryBottleneck {
  domain: RiskDomain;
  statement: string;                        // Plain-language bottleneck sentence
  what_would_change: string;                // Actionable input change suggestion
}

// --- Overall Assessment Result (Section 6) ---

export interface AssessmentResults {
  otr: OtrRiskResult;
  mixing: MixingRiskResult;
  shear: ShearRiskResult;
  co2: Co2RiskResult;
  heat: HeatRiskResult;
  primary_bottleneck: PrimaryBottleneck;
  overall_confidence: Confidence;
}

// --- Flag (soft warnings, Section 3.2) ---

export interface AssessmentFlag {
  domain?: RiskDomain;                      // Which domain the flag relates to (optional)
  message: string;                          // Warning message text
}

// --- Full Assessment (Section 6 Data Model) ---

export interface Assessment {
  id: string;                               // UUID
  user_id: string;                          // UUID
  created_at: string;                       // ISO timestamp
  inputs: ProcessInputs;
  derived: DerivedParameters;
  results: AssessmentResults;
  report_id: string | null;
  flags: AssessmentFlag[];
}

// --- Estimation Transparency (Section 1.4) ---

export interface EstimationTransparency {
  parameters_entered: number;
  parameters_total: number;
  estimated_count: number;
  confidence_label: Confidence;
}

