export const klaVantRietNonCoalescing: KlaCorrelationFn = (op, Pg) => {
  const PgV = Pg / op.V_L;
  return 0.002 * PgV ** 0.7 * op.v_s ** 0.2;
};

// --- Linek et al. (1987) — Rushton, pure water ---

/** kLa = 0.00495 · (Pg/V)^0.593 · Vs^0.4 */
export const klaLinek1987: KlaCorrelationFn = (op, Pg) => {
  const PgV = Pg / op.V_L;
  return 0.00495 * PgV ** 0.593 * op.v_s ** 0.4;
};

// --- Linek et al. (2004) — impeller-type-specific, single impeller ---

/**
 * Rushton:       kLa = 0.0083 · (Pg/V)^0.62 · Vs^0.49
 * Pitched blade: kLa = 0.0063 · (Pg/V)^0.63 · Vs^0.58
 * Hydrofoil/other: kLa = 0.0057 · (Pg/V)^0.67 · Vs^0.56
 */
export const klaLinek2004: KlaCorrelationFn = (op, Pg) => {
  const PgV = Pg / op.V_L;
  const imp = op.impeller_type.toLowerCase();
  if (imp === "rushton" || imp === "smith") {
    return 0.0083 * PgV ** 0.62 * op.v_s ** 0.49;
  }
  if (imp.startsWith("pitched_blade") || imp.startsWith("pbt")) {
    return 0.0063 * PgV ** 0.63 * op.v_s ** 0.58;
  }
  return 0.0057 * PgV ** 0.67 * op.v_s ** 0.56;
};

// --- Moucha et al. (2003) — multi-impeller configurations ---

/**
 * 2×Rushton:              kLa = 0.00379 · (Pg/V)^0.623 · Vs^0.775
 * 3×Rushton:              kLa = 0.00529 · (Pg/V)^0.624 · Vs^0.543
 * Rushton + 2×PBT(down): kLa = 0.00529 · (Pg/V)^0.516 · Vs^0.520
 * Rushton + 2×Hydrofoil: kLa = 0.00480 · (Pg/V)^0.570 · Vs^0.560
 * Default (n_imp ≥ 2):   uses 2×Rushton coefficients
 */
export const klaMoucha2003: KlaCorrelationFn = (op, Pg) => {
  const PgV = Pg / op.V_L;
  // n_imp >= 2 assumed by the select logic; default to 2×Rushton
  return 0.00379 * PgV ** 0.623 * op.v_s ** 0.775;
};

// --- Garcia-Ochoa & Gomez (2004) — viscosity-corrected ---

/**
 * kLa = 0.015 · (Pg/V)^0.6 · Vs^0.6 · (μ_water / μ_eff)^0.5
 * μ_water = 1.0e-3 Pa·s
 */
export const klaGarciaOchoa2004: KlaCorrelationFn = (op, Pg) => {
  const PgV = Pg / op.V_L;
  const mu_w = 1.0e-3;
  const mu_eff = op.mu_L;
  return 0.015 * PgV ** 0.6 * op.v_s ** 0.6 * (mu_w / mu_eff) ** 0.5;
};

// --- Zhu et al. (2001) — non-Newtonian (power-law / CMC) ---

/**
 * kLa = 0.00913 · (Pg/V)^0.64 · Vs^0.30 · (μ_app [mPa·s])^−0.84
 * Metzner-Otto apparent viscosity: μ_app = K · (k_s · N)^(n−1), k_s ≈ 11.5
 */
export const klaZhu2001: KlaCorrelationFn = (op, Pg) => {
  const PgV = Pg / op.V_L;
  const K   = op.K   ?? 1.0e-3;
  const n   = op.n_pl ?? 1.0;
  const k_s = 11.5;
  const mu_app_mPas = K * (k_s * op.N_rps) ** (n - 1) * 1000;
  return 0.00913 * PgV ** 0.64 * op.v_s ** 0.30 * mu_app_mPas ** (-0.84);
};

// --- Registry ---

export const KLA_CORRELATION_REGISTRY: Record<string, KlaCorrelationFn> = {
  vant_riet_coalescing:     klaVantRietCoalescing,
  vant_riet_non_coalescing: klaVantRietNonCoalescing,
  linek_1987:               klaLinek1987,
  linek_2004:               klaLinek2004,
  moucha_2003:              klaMoucha2003,
  garcia_ochoa_2004:        klaGarciaOchoa2004,
  zhu_2001:                 klaZhu2001,
};
---
// Correlation selector — picks the single most appropriate kLa correlation
// given the reactor configuration.
//
// Selection logic (in priority order):
//   power_law broth  → zhu_2001       (designed for power-law CMC fluids)
//   n_imp >= 2       → moucha_2003    (multi-impeller configs)
//   non_coalescing   → vant_riet_non_coalescing
//   default          → linek_2004     (impeller-specific, single, coalescing)

import type { BrothType } from "./types";
import { KLA_CORRELATION_REGISTRY } from "./kla";
import type { KlaCorrelationFn } from "./types";

export type CorrelationKey = keyof typeof KLA_CORRELATION_REGISTRY;

export function selectKlaCorrelation(
  impeller_type: string,
  n_imp: number,
  broth_type: BrothType,
): CorrelationKey {
  if (broth_type === "power_law")     return "zhu_2001";
  if (n_imp >= 2)                     return "moucha_2003";
  if (broth_type === "non_coalescing") return "vant_riet_non_coalescing";
  return "linek_2004";
}

export function getKlaCorrelationFn(key: CorrelationKey): KlaCorrelationFn {
  const fn = KLA_CORRELATION_REGISTRY[key];
  if (!fn) throw new Error(`Unknown kLa correlation: "${key}"`);
  return fn;
}
---
// Gassed power correlations for stirred-tank bioreactors.
// Port of kla_correlations.py gassed power section.

import type { ReactorOperatingPoint } from "./types";

/**
 * Michel & Miller (1962) — Rushton and Smith turbines.
 * Pg = 0.706 · (P₀² · N · d_i³ / Q_g^0.56)^0.45
 * Ref: AIChE J 8:262–266
 */
function michelMiller(P0: number, op: ReactorOperatingPoint): number {
  const Q_safe = Math.max(op.Q_gas, 1e-12);
  return 0.706 * Math.pow((P0 ** 2 * op.N_rps * op.d_i ** 3) / Q_safe ** 0.56, 0.45);
}

/**
 * Cui et al. (1996) — pitched-blade turbines.
 * Pg = 0.648 · (P₀² · N · d_i³ / Q_g^0.56)^0.45
 * Ref: Biotechnol Bioeng 49:456–464
 */
function cui(P0: number, op: ReactorOperatingPoint): number {
  const Q_safe = Math.max(op.Q_gas, 1e-12);
  return 0.648 * Math.pow((P0 ** 2 * op.N_rps * op.d_i ** 3) / Q_safe ** 0.56, 0.45);
}

/**
 * Generic Pg/P0 for low-power-number impellers (hydrofoils, marine).
 * Pg/P0 ≈ 1 − 12 · (Q_g / (N · d_i³)), clamped to [0.3, 1.0].
 */
function generic(P0: number, op: ReactorOperatingPoint): number {
  const N_safe = Math.max(op.N_rps, 1e-6);
  const Fl = op.Q_gas / (N_safe * op.d_i ** 3);
  const ratio = Math.max(0.3, Math.min(1.0, 1.0 - 12.0 * Fl));
  return ratio * P0;
}

/** Ungassed power for a single impeller: P₀ = Np · ρ · N³ · d_i⁵ */
export function ungassedPower(op: ReactorOperatingPoint): number {
  return op.Np * op.rho_L * op.N_rps ** 3 * op.d_i ** 5;
}

/**
 * Total gassed power for the impeller system [W].
 * Selects correlation by impeller type; accounts for multiple impellers.
 */
export function gassedPower(op: ReactorOperatingPoint): number {
  const P0_single = ungassedPower(op);
  const imp = op.impeller_type.toLowerCase();

  let Pg_single: number;
  if (imp === "rushton" || imp === "smith") {
    Pg_single = michelMiller(P0_single, op);
  } else if (imp.startsWith("pitched_blade") || imp.startsWith("pbt")) {
    Pg_single = cui(P0_single, op);
  } else {
    Pg_single = generic(P0_single, op);
  }

  if (op.n_imp > 1) {
    // Interaction factor: closely-spaced impellers lose ~10-20% per impeller
    const spacing_ratio = op.D_T > 0 ? op.D_T / op.D_T : 1.0; // default 1:1 spacing
    const interaction = Math.min(1.0, 0.85 + 0.15 * spacing_ratio);
    return op.n_imp * Pg_single * interaction;
  }

  return Pg_single;
}

/** Specific gassed power P/V [W/m³] */
export function specificPower(op: ReactorOperatingPoint): number {
  return gassedPower(op) / op.V_L;
}

