// Compute achievable kLa using the correlation registry (Stage 4).

import type { ReactorOperatingPoint } from "../correlations/types";
import type { ImpellerType } from "@/lib/types";
import { IMPELLER_CONSTANTS, RHO } from "@/lib/constants";
import { gassedPower } from "../correlations/gassed_power";
import { selectKlaCorrelation, getKlaCorrelationFn } from "../correlations/select";

export interface KlaResult {
  kla_h:       number;  // [h⁻¹]
  Pg:          number;  // Gassed power [W]
  PgV:         number;  // Specific gassed power [W/m³]
  correlation: string;
}

export function buildOperatingPoint(params: {
  D_T: number; H_L: number; V_L: number;
  d_i: number; impeller_type: ImpellerType; n_imp: number;
  N_rps: number; Q_gas: number; v_s: number;
  mu_L: number;
}): ReactorOperatingPoint {
  const Np = IMPELLER_CONSTANTS[params.impeller_type]?.np ?? 5.0;
  return {
    D_T: params.D_T,
    H_L: params.H_L,
    V_L: params.V_L,
    d_i: params.d_i,
    impeller_type: params.impeller_type,
    Np,
    n_imp: params.n_imp,
    N_rps: params.N_rps,
    Q_gas: params.Q_gas,
    v_s: params.v_s,
    rho_L: RHO,
    mu_L: params.mu_L,
    broth_type: "coalescing",  // no UI exposure yet; conservative default
  };
}

/**
 * Compute kLa [h⁻¹]. If Pg is supplied the registry function is called
 * directly (scenario-based); otherwise gassedPower() derives it first.
 */
export function computeKla(op: ReactorOperatingPoint, Pg?: number): KlaResult {
  const Pg_val = Pg ?? gassedPower(op);
  const key    = selectKlaCorrelation(op.impeller_type, op.n_imp, op.broth_type);
  const kla_s  = getKlaCorrelationFn(key)(op, Pg_val);
  return {
    kla_h:       kla_s * 3600,
    Pg:          Pg_val,
    PgV:         Pg_val / op.V_L,
    correlation: key,
  };
}
EOF

