  //     yeast metabolic strategies. Use only when species-specific data are
  //     unavailable.
  other_yeast: {
    mu_max: 0.35,
    Ks:     0.07,
    Ko:     0.005,
    Y_X_S:  0.45,
    Y_O2:   0.65,
  },
