// Barrel re-export — all existing imports from "@/lib/constants" keep working.
// Add new imports from the specific sub-modules for clarity in new code.

export * from "./organisms";
export * from "./equipment";
export * from "./physical";
export * from "./correlations";
export * from "./scoring";
export * from "./defaults";
export * from "./kinetics";

// kLa correlation ensemble selector.
//
// Selection rules:
//   Non-Newtonian (biomass_cdw > threshold):
//     → ["garcia_ochoa_2004", "zhu_2001"]  (any n_imp)
//   Newtonian, n_imp >= 2:
//     → ["vant_riet_coalescing", "vant_riet_non_coalescing",
//         "linek_1987", "linek_2004", "garcia_ochoa_2004", "moucha_2003"]
//   Newtonian, n_imp == 1:
//     → ["vant_riet_coalescing", "vant_riet_non_coalescing",
//         "linek_1987", "linek_2004", "garcia_ochoa_2004"]

import { KLA_CORRELATION_REGISTRY } from "./kla";
import type { KlaCorrelationFn } from "./types";

export type CorrelationKey = keyof typeof KLA_CORRELATION_REGISTRY;

export function selectKlaEnsemble(
  n_imp: number,
  is_non_newtonian: boolean,
): CorrelationKey[] {
  if (is_non_newtonian) {
    return ["garcia_ochoa_2004", "zhu_2001"];
  }
  const base: CorrelationKey[] = [
    "vant_riet_coalescing",
    "vant_riet_non_coalescing",
    "linek_1987",
    "linek_2004",
    "garcia_ochoa_2004",
  ];
  return n_imp >= 2 ? [...base, "moucha_2003"] : base;
}

export function getKlaCorrelationFn(key: CorrelationKey): KlaCorrelationFn {
  const fn = KLA_CORRELATION_REGISTRY[key];
  if (!fn) throw new Error(`Unknown kLa correlation: "${key}"`);
  return fn;
}

// Physical and thermodynamic constants.
// Source: /docs/lemnisca_scaleup_app_dev_spec.md Sections 1.3 and 7

// --- Fluid mechanics ---

/** Broth density (kg/m³) — used in D3, D4, R2, R4, R5 */
export const RHO = 1000;

/** Gravitational acceleration (m/s²) — used in R4 */
export const G = 9.81;

// --- Gas constants ---

/** Molar volume (L/mol at STP) — used in exhaust gas OUR calc */
export const MOLAR_VOLUME_STP = 22.4;

/** Atmospheric pressure (Pa) — used in R4, D6 */
export const ATMOSPHERIC_PRESSURE_PA = 101325;

/** Atmospheric pressure (atm) — used in R4 */
export const ATMOSPHERIC_PRESSURE_ATM = 1;

// --- CO₂ physical properties ---

/** Henry's constant for CO₂ in water (~30°C) (mol/L/atm) — used in R4 */
export const H_CO2 = 0.034;

// --- Lookup table helper ---

export interface LookupPoint {
  temperature: number; // °C
  value: number;
}

export function interpolateTable(table: LookupPoint[], temperature: number): number {
  if (temperature <= table[0].temperature) return table[0].value;
  if (temperature >= table[table.length - 1].temperature) return table[table.length - 1].value;
  for (let i = 0; i < table.length - 1; i++) {
    const t0 = table[i].temperature;
    const t1 = table[i + 1].temperature;
    if (temperature >= t0 && temperature <= t1) {
      const fraction = (temperature - t0) / (t1 - t0);
      return table[i].value + fraction * (table[i + 1].value - table[i].value);
    }
  }
  return table[table.length - 1].value;
}

// --- Viscosity at process temperature (Pa·s) — interpolate linearly ---

export const VISCOSITY_TABLE: LookupPoint[] = [
  { temperature: 20, value: 0.00100 },
  { temperature: 25, value: 0.00089 },
  { temperature: 30, value: 0.00080 },
  { temperature: 37, value: 0.00069 },
  { temperature: 42, value: 0.00062 },
];

// --- Oxygen saturation concentration C* (mmol/L, air, 1 atm) — interpolate linearly ---

export const C_STAR_TABLE: LookupPoint[] = [
  { temperature: 20, value: 0.276 },
  { temperature: 25, value: 0.258 },
  { temperature: 30, value: 0.237 },
  { temperature: 35, value: 0.213 },
  { temperature: 37, value: 0.204 },
  { temperature: 42, value: 0.186 },
];

// --- Non-Newtonian broth rheology ---

/** CDW threshold (g/L) above which broth viscosity becomes non-Newtonian */
export const NON_NEWTONIAN_BIOMASS_THRESHOLD = 60;

/**
 * Quadratic apparent viscosity model (cP), for X ≥ threshold:
 *   μ_app (cP) = NON_NEWTONIAN_MU_A × (X − threshold)²
 *              + NON_NEWTONIAN_MU_B × (X − threshold) + 1
 * Calibration points: 1 cP at X=60, 10 cP at X=100, 50 cP at X=200 g/L CDW.
 */
export const NON_NEWTONIAN_MU_A = 1.25e-3;  // cP · (L/g)²
export const NON_NEWTONIAN_MU_B = 0.175;    // cP · (L/g)

// Calculation engine — derivations D1–D7, risks R1–R5.

import type {
  ProcessInputs,
  DerivedParameters,
  AssessmentFlag,
  OtrRiskResult,
  MixingRiskResult,
  ShearRiskResult,
  Co2RiskResult,
  HeatRiskResult,
  PrimaryBottleneck,
  RiskDomain,
  RiskScore,
} from "@/lib/types";

import { runAllDerivations } from "./derivations/index";
import { calculateOtrRisk }   from "./oxygen/otr_risk";
import { calculateMixingRisk } from "./mixing/mixing_risk";
import { calculateShearRisk }  from "./shear/shear_risk";
import { calculateCo2Risk }    from "./co2/co2_risk";
import { calculateHeatRisk }   from "./heat/heat_risk";

// Re-export derivation helpers for consumers that import from engine
export {
  deriveBiomassCdw,
  deriveOur,
  deriveVesselGeometry,
  derivePowerInput,
  derivePowerFlags,
  deriveReynolds,
  deriveReynoldsFlags,
  deriveGasVelocity,
  deriveDrivingForce,
  runAllDerivations,
} from "./derivations/index";

export type {
  OurResult,
  PowerResult,
  ReynoldsResult,
  FlowRegime,
  GasVelocityResult,
  DrivingForceResult,
  DerivationOutput,
} from "./derivations/index";

export { calculateOtrRisk }    from "./oxygen/otr_risk";
export { calculateMixingRisk } from "./mixing/mixing_risk";
export { calculateShearRisk }  from "./shear/shear_risk";
export { calculateCo2Risk }    from "./co2/co2_risk";
export { calculateHeatRisk }   from "./heat/heat_risk";

// --- Full assessment result ---

export interface PartialAssessmentResult {
  otr:                OtrRiskResult;
  mixing:             MixingRiskResult;
  shear:              ShearRiskResult;
  co2:                Co2RiskResult;
  heat:               HeatRiskResult;
  primary_bottleneck: PrimaryBottleneck;
  flags:              AssessmentFlag[];
  derived:            DerivedParameters;
}

// --- Risk score ordering ---

const SCORE_ORDER: Record<RiskScore, number> = {
  low: 0, moderate: 1, high: 2, critical: 3,
};

function domainRatio(domain: RiskDomain, result: PartialAssessmentResult): number {
  switch (domain) {
    case "otr":     return result.otr.kla_ratio > 0 ? 1 / result.otr.kla_ratio : Infinity;
    case "mixing":  return result.mixing.da != null ? result.mixing.da : result.mixing.theta_mix_target / 30;
    case "shear":   return result.shear.tip_speed_ratio;
    case "co2":     return result.co2.pco2_bottom != null ? result.co2.pco2_bottom / 0.15 : 0;
    case "heat":    return result.heat.heat_ratio;
  }
}

function determinePrimaryBottleneck(result: PartialAssessmentResult): PrimaryBottleneck {
  const domains: { domain: RiskDomain; score: RiskScore }[] = [
    { domain: "otr",    score: result.otr.score },
    { domain: "mixing", score: result.mixing.score },
    { domain: "shear",  score: result.shear.score },
    { domain: "co2",    score: result.co2.score },
    { domain: "heat",   score: result.heat.score },
  ];

  domains.sort((a, b) => {
    const diff = SCORE_ORDER[b.score] - SCORE_ORDER[a.score];
    return diff !== 0 ? diff : domainRatio(b.domain, result) - domainRatio(a.domain, result);
  });

  const primary = domains[0];
  return {
    domain:           primary.domain,
    statement:        generateBottleneckStatement(primary.domain, result),
    what_would_change: generateWhatWouldChange(primary.domain, result),
  };
}

const DOMAIN_LABELS: Record<RiskDomain, string> = {
  otr: "Oxygen transfer", mixing: "Mixing", shear: "Shear stress",
  co2: "CO₂ accumulation", heat: "Heat removal",
};

function generateBottleneckStatement(domain: RiskDomain, result: PartialAssessmentResult): string {
  const label = DOMAIN_LABELS[domain];
  switch (domain) {
    case "otr":
      return `${label} is your critical constraint. Required kLa of ${result.otr.kla_required.toFixed(0)} h⁻¹ versus achievable ${result.otr.kla_target_moderate.toFixed(0)} h⁻¹ at constant P/V.`;
    case "mixing":
      if (result.mixing.da != null) {
        return `${label} is your critical constraint. Mixing time of ${result.mixing.theta_mix_target.toFixed(0)} s at target scale produces Da = ${result.mixing.da.toFixed(2)} — substrate gradients expected.`;
      }
      return `${label} is your critical constraint. Mixing time of ${result.mixing.theta_mix_target.toFixed(0)} s at target scale may compromise pH homogeneity.`;
    case "shear":
      return `${label} is your critical constraint. Tip speed of ${result.shear.tip_speed.toFixed(1)} m/s at constant P/V exceeds organism threshold of ${result.shear.tip_speed_threshold.toFixed(1)} m/s (ratio ${result.shear.tip_speed_ratio.toFixed(2)}).`;
    case "co2":
      return `${label} is your critical constraint. Estimated pCO₂ at vessel bottom is ${(result.co2.pco2_bottom ?? 0).toFixed(2)} bar.`;
    case "heat":
      return `${label} is your critical constraint. Metabolic heat of ${result.heat.q_metabolic.toFixed(1)} kW versus cooling capacity of ${result.heat.q_cool_max.toFixed(1)} kW (ratio ${result.heat.heat_ratio.toFixed(2)}).`;
  }
}

function generateWhatWouldChange(domain: RiskDomain, result: PartialAssessmentResult): string {
  switch (domain) {
    case "otr": {
      const klaReqNeeded = result.otr.kla_target_moderate /
        (result.otr.kla_ratio < 0.7 ? 0.7 : result.otr.kla_ratio < 1.0 ? 1.0 : 1.5);
      return `If your measured OUR is below ${(klaReqNeeded * result.derived.driving_force).toFixed(0)} mmol/L/h, OTR risk improves by one level.`;
    }
    case "mixing":
      if (result.mixing.da != null && result.mixing.da > 0.01) {
        return "Switching to continuous feed would reduce Da and may lower mixing risk.";
      }
      return "Increasing agitation or reducing target vessel H/D ratio would improve mixing time.";
    case "shear":
      return "Switching to a pitched blade turbine or scaling at constant tip speed instead of constant P/V would reduce shear risk.";
    case "co2":
      return "Increasing sparging rate to enhance CO₂ stripping or reducing target vessel H/D ratio would lower pCO₂ at vessel bottom.";
    case "heat": {
      const targetHeatRatio = result.heat.heat_ratio > 1.0 ? 1.0 : result.heat.heat_ratio > 0.85 ? 0.85 : 0.6;
      const dtLmNeeded = (result.heat.q_metabolic / targetHeatRatio * 1000) / (400 * result.heat.a_jacket);
      return `If cooling water is available at a temperature giving ΔT_lm of ${dtLmNeeded.toFixed(1)}°C, heat removal risk improves by one level.`;
    }
  }
}

export function runAssessment(inputs: ProcessInputs): PartialAssessmentResult {
  const { derived, flags } = runAllDerivations(inputs);

  const otr     = calculateOtrRisk(inputs, derived);
  flags.push(...otr.flags);

  const mixing  = calculateMixingRisk(inputs, derived);
  flags.push(...mixing.flags);

  const shear   = calculateShearRisk(inputs, derived);
  flags.push(...shear.flags);

  const co2     = calculateCo2Risk(inputs, derived);
  flags.push(...co2.flags);

  const heat    = calculateHeatRisk(inputs, derived);
  flags.push(...heat.flags);

  const partialResult: PartialAssessmentResult = {
    otr:                otr.result,
    mixing:             mixing.result,
    shear:              shear.result,
    co2:                co2.result,
    heat:               heat.result,
    primary_bottleneck: null as unknown as PrimaryBottleneck,
    flags,
    derived,
  };

  partialResult.primary_bottleneck = determinePrimaryBottleneck(partialResult);
  return partialResult;
}

// D4 + D6 — Viscosity, Reynolds number, and oxygen driving force.

import type { AssessmentFlag } from "@/lib/types";
import { VISCOSITY_TABLE, C_STAR_TABLE, RHO, interpolateTable } from "@/lib/constants";

// --- Viscosity ---

export function deriveViscosity(temperature: number): number {
  return interpolateTable(VISCOSITY_TABLE, temperature);
}

// --- D4: Reynolds number ---

export type FlowRegime = "turbulent" | "transitional" | "laminar";

export interface ReynoldsResult {
  re:     number;
  regime: FlowRegime;
}

export function deriveReynolds(
  n_rps: number,
  d_imp: number,
  mu:    number,
): ReynoldsResult {
  const re = (RHO * n_rps * d_imp * d_imp) / mu;
  const regime: FlowRegime =
    re > 10000 ? "turbulent" : re >= 1000 ? "transitional" : "laminar";
  return { re, regime };
}

export function deriveReynoldsFlags(regime: FlowRegime): AssessmentFlag[] {
  if (regime === "transitional")
    return [{ message: "Transitional flow regime — power number assumption may not hold." }];
  if (regime === "laminar")
    return [{ message: "Laminar flow — correlations invalid." }];
  return [];
}

// --- D6: C* and driving force ---

export interface DrivingForceResult {
  c_star:        number; // mmol/L
  c_l:           number; // mmol/L at DO setpoint
  driving_force: number; // c_star - c_l
}

export function deriveDrivingForce(
  temperature:  number,
  do_setpoint: number,
): DrivingForceResult {
  const c_star       = interpolateTable(C_STAR_TABLE, temperature);
  const c_l          = (do_setpoint / 100) * c_star;
  const driving_force = c_star - c_l;
  return { c_star, c_l, driving_force };
}

