78	  // q_gas_target is m³/s; convert to NL/h for molar flow (STP: 1 mol = 22.4 L).
79	  const v_liquid_l    = derived.target_geometry.volume_m3 * 1000;
80	  const q_gas_nl_h    = derived.q_gas_target * 1e3 * 3600;          // NL/h
81	  const n_dot_gas_mol = q_gas_nl_h / MOLAR_VOL;                     // mol/h
82	  const cer_mol_h     = (cer / 1000) * v_liquid_l;                  // mol CO₂/h from broth
83	  const y_co2_out     = Math.min(Y_CO2_IN + cer_mol_h / n_dot_gas_mol, 0.20); // cap at 20%
84	
85	  // Log-mean gas-phase pCO₂ across vessel height (bar).
86	  const p_total_bar   = (ATMOSPHERIC_PRESSURE_PA + RHO * G * derived.target_geometry.h_liquid / 2) / 1e5;
87	  const pco2_gas_in   = Y_CO2_IN  * 1.01325;  // bar (inlet ≈ air)
88	  const pco2_gas_out  = y_co2_out * p_total_bar;
89	  const pco2_gas_avg  = logMean(pco2_gas_out, pco2_gas_in);
90	
91	  // Dissolved CO₂ = gas-phase equilibrium + transfer driving force contribution.
92	  // Steady-state: kLa·(C_L − C*) = CER  →  C_L − C* = CER/kLa
93	  // C* ≈ pco2_gas_avg / H_CO2 (Henry's law; H_CO2 in mmol/L/atm, pco2_gas_avg in bar ≈ atm)
94	  const pco2_gas_avg_atm = pco2_gas_avg / 1.01325;
95	  const pco2_bulk_atm    = pco2_gas_avg_atm + (cer / 1000) / (kla_co2 * H_CO2);
96	  const pco2_bulk        = pco2_bulk_atm * 1.01325;
97	
98	  // Hydrostatic correction: pCO₂ at sparger reflects higher local pressure.
99	  const dp_hydro    = RHO * G * derived.target_geometry.h_liquid;
100	  const pco2_bottom = pco2_bulk * (ATMOSPHERIC_PRESSURE_PA + dp_hydro) / ATMOSPHERIC_PRESSURE_PA;
101	
102	  const pco2_margin = pco2_critical / pco2_bottom;
103	  const score       = scorePco2Margin(pco2_margin);
104	
105	  return {
106	    result: {
107	      score, activated: true,
108	      cer, kla_co2,
109	      y_co2_out, pco2_gas_avg,
110	      pco2_bulk, pco2_bottom, dp_hydro,
111	      pco2_critical, pco2_margin,
112	      confidence, driver,
113	    },
114	    flags,
115	  };
116	}

